/**
 * SEO component that queries for data with
 *  Gatsby's useStaticQuery React hook
 *
 * See: https://www.gatsbyjs.com/docs/use-static-query/
 */

import React from 'react';
import { Helmet } from 'react-helmet';
import thumbImg from '../../../images/savethedate/metaThumb.webp';

export const Seo = () => {
  const metaTitle = 'Save The Date 13.05.2024'
  const metaDescription = 'Hiếu & Phương Trân Trọng Kính Mời';
  const metaThumbnail = `https://www.hieugoesto.com${thumbImg}`;
  const metaUrl = 'https://www.hieugoesto.com/savethedate';
  const metaAuthor = 'H&P';

  const googleMetaTags = [
    {
      name: 'description',
      content: metaDescription,
    },
    {
      name: 'author',
      content: metaAuthor,
    }
  ]

  const facebookMetaTags = [
    {
      property: 'og:title',
      content: metaTitle,
    },
    {
      property: 'og:description',
      content: metaDescription,
    },
    {
      property: 'og:type',
      content: 'website',
    },
    {
      property: 'og:image',
      content: metaThumbnail,
    },
    {
      property: 'og:url',
      content: metaUrl,
    },
    {
      property: 'fb:app_id',
      content: '272354566715786',
    }
  ]

  const twitterMetaTags = [
    {
      name: 'twitter:card',
      content: 'summary',
    },
    {
      name: 'twitter:creator',
      content: metaAuthor,
    },
    {
      name: 'twitter:title',
      content: metaTitle,
    },
    {
      name: 'twitter:description',
      content: metaDescription,
    },
    {
      name: 'twitter:image',
      content: metaThumbnail,
    }
  ]

  return (
    <Helmet
      htmlAttributes={{
        lang: 'en',
      }}
      bodyAttributes={{
        class: '',
      }}
      title={metaTitle}
      titleTemplate={`%s | ${metaTitle}`}
      meta={[
        ...googleMetaTags,
        ...facebookMetaTags,
        ...twitterMetaTags,
      ]}
      link={
        [{
          rel: 'canonical',
          key: metaUrl,
          href: metaUrl
        }]
      }
    >
      <link rel="prefetch" href={ thumbImg } />
    </Helmet>
  )
}
